export default function AdminHomeFeatures() {
  const [items, setItems] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    title: "", description: "", mediaType: "image", mediaUrl: "", featuresList: "", buttonText: "Explore Our Wedding Frame", buttonLink: "/portfolio"
  });

  useEffect(() => {
    fetchItems();
  }, []);

  const fetchItems = async () => {
    const res = await fetch("/api/home-features");
    const data = await res.json();
    if (data.success) setItems(data.data);
    setLoading(false);
  };

  const handleImageFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({ ...formData, mediaUrl: reader.result as string });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const payload = {
      ...formData,
      featuresList: formData.featuresList.split('\n').filter(Boolean)
    };

    const url = editingId ? `/api/home-features/${editingId}` : "/api/home-features";
    const method = editingId ? "PUT" : "POST";

    await fetch(url, {
      method,
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    setShowModal(false);
    setEditingId(null);
    setFormData({
      title: "", description: "", mediaType: "image", mediaUrl: "", featuresList: "", buttonText: "Explore Our Wedding Frame", buttonLink: "/portfolio"
    });
    fetchItems();
  };

  const handleEditClick = (item: any) => {
    setEditingId(item._id);
    setFormData({
      title: item.title || "",
      description: item.description || "",
      mediaType: item.mediaType || "image",
      mediaUrl: item.mediaUrl || "",
      featuresList: Array.isArray(item.featuresList) ? item.featuresList.join('\n') : (item.featuresList || ""),
      buttonText: item.buttonText || "Explore Our Wedding Frame",
      buttonLink: item.buttonLink || "/portfolio",
    });
    setShowModal(true);
  };

  const handleDelete = async (id: string) => {
    if (confirm("Are you sure?")) {
      await fetch(`/api/home-features/${id}`, { method: "DELETE" });
      fetchItems();
    }
  };

  return (
    <div className="p-8 font-outfit text-white">
      <header className="mb-8 flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-playfair font-medium">Home Features</h1>
          <p className="text-neutral-400 mt-2 text-sm">Manage dynamic sections on the homepage.</p>
        </div>
        <button 
          onClick={() => {
            setEditingId(null);
            setFormData({ title: "", description: "", mediaType: "image", mediaUrl: "", featuresList: "", buttonText: "Explore Our Wedding Frame", buttonLink: "/portfolio" });
            setShowModal(true);
          }}
          className="flex items-center gap-2 bg-gold-500 hover:bg-gold-400 text-black px-6 py-2 rounded-lg font-semibold transition-colors"
        >
          <Plus size={18} /> Add Feature Section
        </button>
      </header>

      {loading ? (
        <div>Loading...</div>
      ) : (
        <div className="bg-neutral-900 border border-white/10 rounded-2xl overflow-hidden">
          <table className="w-full text-left">
            <thead className="bg-neutral-950 border-b border-white/10 text-neutral-400 text-sm">
              <tr>
                <th className="px-6 py-4 font-medium">Type</th>
                <th className="px-6 py-4 font-medium">Title</th>
                <th className="px-6 py-4 font-medium">URL</th>
                <th className="px-6 py-4 font-medium text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/10">
              {items.map((item) => (
                <tr key={item._id} className="hover:bg-white/5 transition-colors">
                  <td className="px-6 py-4 capitalize">{item.mediaType}</td>
                  <td className="px-6 py-4 font-medium">{item.title}</td>
                  <td className="px-6 py-4 text-neutral-400 max-w-[200px] truncate">{item.mediaUrl}</td>
                  <td className="px-6 py-4 text-right">
                    <button onClick={() => handleEditClick(item)} className="text-neutral-400 hover:text-white mr-4"><Edit2 size={18} /></button>
                    <button onClick={() => handleDelete(item._id)} className="text-neutral-400 hover:text-red-500"><Trash2 size={18} /></button>
                  </td>
                </tr>
              ))}
              {items.length === 0 && (
                <tr>
                  <td colSpan={4} className="px-6 py-8 text-center text-neutral-500">No home features found.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}

      {showModal && (
        <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 p-4 overflow-y-auto">
          <form onSubmit={handleSubmit} className="bg-neutral-900 border border-white/10 rounded-2xl p-8 max-w-2xl w-full my-8">
            <h2 className="text-2xl font-playfair mb-6">{editingId ? "Edit Home Feature Section" : "Add Home Feature Section"}</h2>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-neutral-400 mb-1">Section Title *</label>
                <input required placeholder="Section Title" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} className="w-full bg-neutral-950 border border-white/10 rounded-lg p-3 outline-none focus:border-gold-500" />
              </div>
              <div>
                <label className="block text-sm font-medium text-neutral-400 mb-1">Description text *</label>
                <textarea required placeholder="Description text" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} className="w-full bg-neutral-950 border border-white/10 rounded-lg p-3 outline-none focus:border-gold-500" rows={4}></textarea>
              </div>
              <div>
                <label className="block text-sm font-medium text-neutral-400 mb-1">Media Type *</label>
                <select value={formData.mediaType} onChange={e => setFormData({...formData, mediaType: e.target.value})} className="w-full bg-neutral-950 border border-white/10 rounded-lg p-3 outline-none focus:border-gold-500 text-white">
                  <option value="image">Image</option>
                  <option value="video">YouTube Video</option>
                </select>
              </div>
              <div>
                {formData.mediaType === 'image' && (
                  <div className="mb-3">
                    <label className="block text-sm font-medium text-neutral-400 mb-2">Upload Image File</label>
                    <input
                      type="file"
                      accept="image/*"
                      onChange={handleImageFileChange}
                      className="w-full bg-neutral-950 border border-white/10 rounded-lg p-3 outline-none focus:border-gold-500 text-sm text-neutral-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-xs file:font-semibold file:bg-gold-500 file:text-black hover:file:bg-gold-400"
                    />
                  </div>
                )}
                <label className="block text-sm font-medium text-neutral-400 mb-1">
                  {formData.mediaType === 'video' ? "YouTube Embed URL * (e.g. https://www.youtube.com/embed/...)" : "Or enter Image URL"}
                </label>
                <input required={formData.mediaType === 'video'} placeholder={formData.mediaType === 'video' ? "YouTube Embed URL" : "Image URL"} value={formData.mediaUrl.startsWith("data:") ? "" : formData.mediaUrl} onChange={e => setFormData({...formData, mediaUrl: e.target.value})} className="w-full bg-neutral-950 border border-white/10 rounded-lg p-3 outline-none focus:border-gold-500" />
              </div>
              <div>
                <label className="block text-sm font-medium text-neutral-400 mb-1">Feature List (optional, one per line)</label>
                <textarea placeholder="Feature List (optional, one per line)" value={formData.featuresList} onChange={e => setFormData({...formData, featuresList: e.target.value})} className="w-full bg-neutral-950 border border-white/10 rounded-lg p-3 outline-none focus:border-gold-500" rows={4}></textarea>
              </div>
              <div className="flex gap-4">
                <div className="w-1/2">
                  <label className="block text-sm font-medium text-neutral-400 mb-1">Button Text *</label>
                  <input required placeholder="Button Text" value={formData.buttonText} onChange={e => setFormData({...formData, buttonText: e.target.value})} className="w-full bg-neutral-950 border border-white/10 rounded-lg p-3 outline-none focus:border-gold-500" />
                </div>
                <div className="w-1/2">
                  <label className="block text-sm font-medium text-neutral-400 mb-1">Button Link *</label>
                  <input required placeholder="Button Link" value={formData.buttonLink} onChange={e => setFormData({...formData, buttonLink: e.target.value})} className="w-full bg-neutral-950 border border-white/10 rounded-lg p-3 outline-none focus:border-gold-500" />
                </div>
              </div>
            </div>

            {formData.mediaType === 'image' && formData.mediaUrl && (
              <div className="mt-4 relative h-32 rounded-lg overflow-hidden border border-white/10">
                <img src={formData.mediaUrl} alt="Preview" className="w-full h-full object-cover" />
              </div>
            )}

            <div className="mt-8 flex justify-end gap-4">
              <button type="button" onClick={() => {
                setShowModal(false);
                setEditingId(null);
              }} className="px-6 py-2 text-neutral-400 hover:text-white">Cancel</button>
              <button type="submit" className="bg-gold-500 hover:bg-gold-400 text-black px-6 py-2 rounded-lg font-semibold">Save Section</button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

